function drawEducationAsset(kind){return(ctx,s,color='#55a8bc',t=0,action='none',label='')=>{ctx.save();ctx.shadowColor='#102b3d66';ctx.shadowBlur=s*.06;ctx.fillStyle='#f7f4e8';ctx.strokeStyle='#517f91';ctx.lineWidth=s*.025;ctx.beginPath();ctx.roundRect(-s*.42,-s*.34,s*.84,s*.68,s*.09);ctx.fill();ctx.stroke();ctx.shadowBlur=0;const title=String(label||educationNames[kind]||kind).slice(0,19);ctx.fillStyle='#28495c';ctx.font=`700 ${Math.max(8,Math.round(s*.075))}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(title,0,-s*.23,s*.72);
if(['map_globe','topographic_map','population_map','settlement_map','resource_map','vietnam_map','island_map','economic_region_map','land_use_map','historical_trade_route'].includes(kind)){ctx.fillStyle='#d9ead7';ctx.beginPath();ctx.roundRect(-s*.33,-s*.13,s*.66,s*.38,s*.04);ctx.fill();ctx.strokeStyle='#a4c6b0';ctx.lineWidth=s*.012;for(let i=0;i<4;i++){ctx.beginPath();ctx.ellipse(0,s*(.04+i*.04),s*(.12+i*.05),s*(.04+i*.013),-.18,0,TAU);ctx.stroke();}ctx.strokeStyle=kind==='historical_trade_route'?'#d47e52':'#4a9d91';ctx.lineWidth=s*.018;ctx.beginPath();ctx.moveTo(-s*.25,s*.13);ctx.quadraticCurveTo(-s*.04,-s*.08,s*.02,s*.12);ctx.quadraticCurveTo(s*.12,s*.25,s*.26,-s*.02);ctx.stroke();ctx.fillStyle='#db7657';for(const [x,y] of [[-.2,.03],[.02,.11],[.23,-.02]]){ctx.beginPath();ctx.arc(s*x,s*y,s*.025,0,TAU);ctx.fill();}}
else if(['contour_lines','mountain_cross_section','delta_landform','coastal_landform','volcano_cutaway','river_basin','sea_floor','rock_cycle'].includes(kind)){ctx.fillStyle=kind==='sea_floor'?'#77b8c7':'#98c88b';ctx.beginPath();if(kind==='volcano_cutaway'){ctx.moveTo(-s*.32,s*.16);ctx.lineTo(-s*.18,-s*.08);ctx.lineTo(-s*.05,-s*.01);ctx.lineTo(s*.05,-s*.27);ctx.lineTo(s*.18,-s*.04);ctx.lineTo(s*.32,s*.16);}else{ctx.moveTo(-s*.34,s*.13);ctx.quadraticCurveTo(-s*.16,-s*.26,0,s*.03);ctx.quadraticCurveTo(s*.18,-s*.16,s*.34,s*.13);}ctx.lineTo(s*.34,s*.20);ctx.lineTo(-s*.34,s*.20);ctx.fill();ctx.strokeStyle='#fff3ce';ctx.lineWidth=s*.014;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(0,s*(.02+i*.045),s*(.11+i*.055),s*(.045+i*.014),0,0,Math.PI);ctx.stroke();}if(['river_basin','delta_landform','coastal_landform','sea_floor'].includes(kind)){ctx.strokeStyle='#398dc2';ctx.lineWidth=s*.035;ctx.beginPath();ctx.moveTo(-s*.25,s*.04);ctx.quadraticCurveTo(-s*.02,-s*.03,s*.04,s*.12);ctx.quadraticCurveTo(s*.12,s*.19,s*.27,s*.04);ctx.stroke();}}
else if(['climate_chart','population_pyramid','bar_chart','line_chart'].includes(kind)){ctx.strokeStyle='#8098a3';ctx.lineWidth=s*.012;ctx.beginPath();ctx.moveTo(-s*.28,s*.16);ctx.lineTo(s*.28,s*.16);ctx.moveTo(-s*.25,s*.15);ctx.lineTo(-s*.25,-s*.13);ctx.stroke();if(kind==='population_pyramid'){for(let i=0;i<4;i++){ctx.fillStyle=i%2?'#53a8bd':'#e6a16d';ctx.fillRect(-s*.02-s*(.045+i*.025),-s*.10+i*s*.065,s*(.045+i*.025),s*.05);ctx.fillRect(s*.02,-s*.10+i*s*.065,s*(.045+i*.025),s*.05);}}else{for(let i=0;i<5;i++){ctx.fillStyle=['#5ba8bc','#edb65f','#67ad86','#d98568','#897cca'][i];ctx.fillRect(-s*.19+i*s*.08,s*(.11-(i%3)*.065),s*.045,s*(.05+(i%3)*.065));}ctx.strokeStyle='#dc765e';ctx.lineWidth=s*.02;ctx.beginPath();ctx.moveTo(-s*.20,s*.06);ctx.lineTo(-s*.08,-s*.03);ctx.lineTo(s*.03,s*.04);ctx.lineTo(s*.17,-s*.12);ctx.stroke();}}
else if(kind.includes('cell')||kind==='bacteria'||kind==='virus'){ctx.fillStyle=kind==='plant_cell'?'#b5d99b':'#a9d9d8';ctx.beginPath();ctx.ellipse(0,s*.035,s*.26,s*.15,0,0,TAU);ctx.fill();ctx.strokeStyle='#5b9e8d';ctx.lineWidth=s*.016;ctx.stroke();ctx.fillStyle='#8277bd';ctx.beginPath();ctx.arc(s*.02,s*.035,s*.055,0,TAU);ctx.fill();for(let i=0;i<6;i++){ctx.fillStyle=i%2?'#e4a96c':'#5cabc0';ctx.beginPath();ctx.arc(-s*.19+(i%3)*s*.15,-s*.06+Math.floor(i/3)*s*.14,s*.018,0,TAU);ctx.fill();}}
else if(['timeline','sun_dial','bronze_drum','inscription_stone','ancient_vase','artifact','museum_case','archive_box','historic_document','excavation_site','archaeology_brush','temple_ruins','citadel_gate','traditional_house','ancient_ship','royal_seal'].includes(kind)){ctx.fillStyle=kind==='bronze_drum'?'#c89548':'#d6bc84';ctx.beginPath();ctx.roundRect(-s*.25,-s*.12,s*.5,s*.31,s*.04);ctx.fill();ctx.strokeStyle='#8f6841';ctx.lineWidth=s*.018;ctx.stroke();if(kind==='timeline'){ctx.strokeStyle='#4c8797';ctx.beginPath();ctx.moveTo(-s*.22,s*.04);ctx.lineTo(s*.22,s*.04);ctx.stroke();for(let i=0;i<4;i++){ctx.fillStyle='#d47758';ctx.beginPath();ctx.arc(-s*.20+i*s*.13,s*.04,s*.026,0,TAU);ctx.fill();}}else{ctx.strokeStyle='#f6df9c';for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(0,s*.02,s*(.05+i*.045),0,TAU);ctx.stroke();}}}
else{ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,s*.015,s*.16,0,TAU);ctx.fill();ctx.fillStyle='#f7f4e8';ctx.font=`700 ${Math.max(10,Math.round(s*.10))}px system-ui`;ctx.fillText(kind.startsWith('circuit')?'＋':kind==='wind_vane'?'↗':kind==='water_cycle'?'↻':'✦',0,s*.055);}ctx.restore();};}
function drawMeasurementAsset(kind){return(ctx,s,color='#55a8bc',t=0,action='none')=>{
 ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.shadowColor='#122b3b55';ctx.shadowBlur=s*.035;
 if(kind==='ruler'){
  const x=-s*.43,y=-s*.16,w=s*.86,h=s*.32,g=ctx.createLinearGradient(0,y,0,y+h);g.addColorStop(0,'#f7cf78');g.addColorStop(.52,'#e9b956');g.addColorStop(1,'#c88e3d');
  ctx.fillStyle=g;ctx.beginPath();ctx.roundRect(x,y,w,h,s*.045);ctx.fill();ctx.strokeStyle='#9e7139';ctx.lineWidth=s*.012;ctx.stroke();
  ctx.fillStyle='#fff1c4';ctx.fillRect(x+s*.035,y+s*.035,s*.075,h-s*.07);ctx.fillStyle='#8a602e';ctx.font=`600 ${Math.max(7,Math.round(s*.048))}px system-ui`;ctx.textAlign='center';ctx.textBaseline='top';
  for(let i=0;i<=20;i++){const px=x+s*.13+i*w*.82/20,len=i%5===0?s*.105:i%5===0?s*.08:s*.052;ctx.strokeStyle='#714d29';ctx.lineWidth=s*.006;ctx.beginPath();ctx.moveTo(px,y);ctx.lineTo(px,y+len);ctx.stroke();if(i%5===0&&i<20)ctx.fillText(String(i),px,y+s*.115);}
  const marker=x+s*.13+(Math.sin(t*.8)*.5+.5)*w*.82;ctx.strokeStyle='#e35f52';ctx.lineWidth=s*.012;ctx.beginPath();ctx.moveTo(marker,y-s*.025);ctx.lineTo(marker,y+s*.045);ctx.stroke();
 }else if(kind==='balance_scale'){
  ctx.fillStyle='#8b6a4f';ctx.beginPath();ctx.roundRect(-s*.055,-s*.05,s*.11,s*.34,s*.025);ctx.fill();ctx.fillStyle='#c58a50';ctx.beginPath();ctx.moveTo(-s*.23,s*.29);ctx.lineTo(s*.23,s*.29);ctx.lineTo(s*.17,s*.22);ctx.lineTo(-s*.17,s*.22);ctx.closePath();ctx.fill();
  const tilt=Math.sin(t*1.15)*.055;ctx.save();ctx.translate(0,-s*.04);ctx.rotate(tilt);ctx.strokeStyle='#557d89';ctx.lineWidth=s*.035;ctx.beginPath();ctx.moveTo(-s*.34,-s*.13);ctx.lineTo(s*.34,-s*.13);ctx.stroke();ctx.fillStyle='#d7a95d';ctx.beginPath();ctx.arc(0,-s*.13,s*.055,0,TAU);ctx.fill();
  for(const side of [-1,1]){const px=side*s*.29;ctx.strokeStyle='#78939a';ctx.lineWidth=s*.012;ctx.beginPath();ctx.moveTo(px,-s*.13);ctx.lineTo(px-side*tilt*s*.24,s*.12);ctx.stroke();ctx.fillStyle=side<0?'#67b5c0':'#e5a75a';ctx.beginPath();ctx.moveTo(px-s*.12,s*.12);ctx.quadraticCurveTo(px,s*.24,px+s*.12,s*.12);ctx.lineTo(px+s*.12,s*.10);ctx.lineTo(px-s*.12,s*.10);ctx.closePath();ctx.fill();ctx.strokeStyle='#6e7d78';ctx.lineWidth=s*.009;ctx.stroke();ctx.fillStyle='#8f6c4c';ctx.beginPath();ctx.arc(px,s*.07,s*.035,0,TAU);ctx.fill();}ctx.restore();
 }else if(kind==='stopwatch'){
  ctx.fillStyle='#b6cbd0';ctx.beginPath();ctx.roundRect(-s*.09,-s*.43,s*.18,s*.15,s*.035);ctx.fill();ctx.fillStyle='#738f98';ctx.beginPath();ctx.roundRect(-s*.035,-s*.49,s*.07,s*.12,s*.02);ctx.fill();
  const g=ctx.createRadialGradient(-s*.08,-s*.10,s*.03,0,0,s*.34);g.addColorStop(0,'#fffef2');g.addColorStop(1,'#d7e4df');ctx.fillStyle=g;ctx.strokeStyle='#526f7a';ctx.lineWidth=s*.035;ctx.beginPath();ctx.arc(0,s*.02,s*.32,0,TAU);ctx.fill();ctx.stroke();
  for(let i=0;i<12;i++){const a=i*TAU/12-Math.PI/2;ctx.strokeStyle='#48616a';ctx.lineWidth=i%3===0?s*.016:s*.009;ctx.beginPath();ctx.moveTo(Math.cos(a)*s*.265, s*.02+Math.sin(a)*s*.265);ctx.lineTo(Math.cos(a)*s*(i%3===0?.225:.24),s*.02+Math.sin(a)*s*(i%3===0?.225:.24));ctx.stroke();}
  ctx.strokeStyle='#de6658';ctx.lineWidth=s*.018;ctx.beginPath();ctx.moveTo(0,s*.02);ctx.lineTo(Math.cos(t*TAU)*s*.21,s*.02+Math.sin(t*TAU)*s*.21);ctx.stroke();ctx.strokeStyle='#405d69';ctx.lineWidth=s*.028;ctx.beginPath();ctx.moveTo(0,s*.02);ctx.lineTo(Math.cos(t*TAU/60-Math.PI/2)*s*.14,s*.02+Math.sin(t*TAU/60-Math.PI/2)*s*.14);ctx.stroke();ctx.fillStyle='#405d69';ctx.beginPath();ctx.arc(0,s*.02,s*.03,0,TAU);ctx.fill();
 }else if(kind==='thermometer'){
  ctx.fillStyle='#dce9e7';ctx.strokeStyle='#668792';ctx.lineWidth=s*.025;ctx.beginPath();ctx.roundRect(-s*.105,-s*.41,s*.21,s*.70,s*.10);ctx.fill();ctx.stroke();ctx.fillStyle='#d9564e';ctx.beginPath();ctx.arc(0,s*.27,s*.105,0,TAU);ctx.fill();
  const level=.08+.26*(.5+.5*Math.sin(t*.72));ctx.fillStyle='#e85d51';ctx.beginPath();ctx.roundRect(-s*.035,s*.24-level,s*.07,level,s*.025);ctx.fill();ctx.strokeStyle='#586f78';ctx.lineWidth=s*.009;for(let i=0;i<8;i++){const yy=s*(.18-i*.065);ctx.beginPath();ctx.moveTo(s*.055,yy);ctx.lineTo(s*(i%2===0?.13:.105),yy);ctx.stroke();}ctx.fillStyle='#556f78';ctx.font=`600 ${Math.max(7,Math.round(s*.045))}px system-ui`;ctx.textAlign='left';ctx.fillText('°C',s*.14,-s*.26);
 }
 ctx.restore();
};}
for(const kind of ['ruler','balance_scale','stopwatch','thermometer'])DRAW[kind]=drawMeasurementAsset(kind);
for(const kind of educationIds){shortNames[kind]=educationNames[kind]||kind.replaceAll('_',' ').toUpperCase();DRAW[kind]=drawEducationAsset(kind);}

export const illustrationTypes=[...TYPES];
export function drawCanvas2DAsset(ctx,type,size,color='#f5ba62',time=0,action='none',label='',assetProperties={}) { const draw=DRAW[type]; if(draw) draw(ctx,size,color,time,action,label,assetProperties); }
export function renderCanvas2DActors(ctx,width,height,scene,time,poses=new Map()){
 const illustrations=scene.illustrations||[];
 for(let index=0;index<illustrations.length;index++){
  const item=illustrations[index],type=TYPES.has(item.type)?item.type:'star',draw=DRAW[type];
  if(!draw)continue;
  const pose=poses.get(index),anchor=POSITIONS[item.position]||POSITIONS[scene.composition?.subject_position]||POSITIONS.center;
  const x=Number.isFinite(pose?.x)?pose.x:anchor[0],y=Number.isFinite(pose?.y)?pose.y:anchor[1];
  const scale=clamp(Number(item.scale)||1,.3,1.5)*(Number.isFinite(pose?.scale)?clamp(pose.scale,.1,3):1);
  const size=scale*Math.min(width,height)*.24,opacity=clamp(Number.isFinite(pose?.opacity)?pose.opacity:Number(item.opacity??1),0,1);
  const rotation=Number.isFinite(pose?.rotation)?pose.rotation:0;
  ctx.save();ctx.translate(width*x,height*y);ctx.rotate(rotation);ctx.globalAlpha=opacity;ctx.shadowColor='#08101b88';ctx.shadowBlur=size*.08;
  draw(ctx,size,item.color||'#f5ba62',time,item.action||'none',item.label||'');ctx.restore();
 }
}
export function renderIllustrations(ctx,width,height,scene,time){const portrait=width/height<.9,titleTop=portrait?.16:.24,titleBottom=portrait?.37:.47,titleLeft=portrait?.06:.055,titleRight=portrait?.94:.57,safe=clamp(Number(scene.composition?.safe_margin)||.08,.04,.2);for(const [index,item] of (scene.illustrations||[]).entries()){const type=TYPES.has(item.type)?item.type:'star',draw=DRAW[type];if(!draw)continue;const raw=POSITIONS[item.position]||POSITIONS[scene.composition?.subject_position]||POSITIONS.center,size=clamp(Number(item.scale)||1,.3,1.5)*Math.min(width,height)*.24,radiusX=size*.54/width,radiusY=size*.54/height,px=clamp(raw[0],safe+radiusX,1-safe-radiusX);let py=clamp(raw[1],safe+radiusY,1-safe-radiusY);if(px+radiusX>titleLeft&&px-radiusX<titleRight&&py+radiusY>titleTop&&py-radiusY<titleBottom){const below=titleBottom+radiusY+.025,above=titleTop-radiusY-.025;py=below+radiusY<=1-safe?below:above-radiusY>=safe?above:clamp(.68,safe+radiusY,1-safe-radiusY);}const phase=time*(item.action==='spin'?2:item.action==='pulse'?1.6:1),drift=item.action==='fly'||item.action==='drive'||item.action==='walk'?Math.sin(time*1.2+index)*width*(item.action==='walk'?.025:.055):0,fall=item.action==='fall'?(time*height*.25+index*height*.19)%(height*.30):0,float=item.action==='float'||item.action==='fly'?Math.sin(time*1.7+index)*height*.018:item.action==='bounce'||item.action==='jump'?Math.abs(Math.sin(time*3+index))*height*(item.action==='jump'?.07:.045):0,drawTime=item.action==='none'?0:time+index*.31;ctx.save();ctx.translate(width*px+drift,height*py+float+fall);if(item.action==='spin')ctx.rotate(phase);if(item.action==='pulse')ctx.scale(1+.08*Math.sin(phase),1+.08*Math.sin(phase));if(item.action==='wobble')ctx.rotate(Math.sin(time*5+index)*.10);ctx.globalAlpha=clamp(Number(item.opacity??1),.2,1);ctx.shadowColor='#08101b88';ctx.shadowBlur=size*.08;draw(ctx,size,item.color||'#f5ba62',drawTime,item.action,item.label||'');ctx.restore();}}
